usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Skills.Versions.New(
		context.TODO(),
		"skill_123",
		openai.SkillVersionNewParams{
			Files: []string{"Example data"},
			Default: param.NewOpt[bool](true),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
